package com.bank.compliance.service;

import java.util.Arrays;
import java.util.logging.Logger;

// Counts triplets (three-fee bundles) whose sum is strictly less than a cap.
public class FeeBundleCounter {
    private static final Logger log = Logger.getLogger(FeeBundleCounter.class.getName());

    public long countBundlesUnderCap(int[] fees, int cap) {
        if (fees == null || fees.length < 3) return 0L;
        Arrays.sort(fees);
        long count = 0L;

        for (int i = 0; i < fees.length - 2; i++) {
            int left = i + 1;
            int right = fees.length - 1;
            while (left < right) {
                int sum = fees[i] + fees[left] + fees[right];
                if (sum < cap) {
                    // Every element between left and right also qualifies.
                    count += (right - left);
                    left++;
                } else {
                    right--; // sum too big, shrink from the large end
                }
            }
        }
        final long total = count;
        log.info(() -> "Bundles under cap " + cap + " = " + total);
        return count;
    }
}
