package com.bank.compliance;

import com.bank.compliance.service.FeeBundleCounter;
import java.util.logging.Logger;

public class FeeBundleDemo {
    private static final Logger log = Logger.getLogger(FeeBundleDemo.class.getName());

    public static void main(String[] args) {
        // Fee amounts (in rupees) and the regulatory cap.
        int[] fees = {1, 2, 3, 4};
        int cap = 7;

        FeeBundleCounter counter = new FeeBundleCounter();
        long safe = counter.countBundlesUnderCap(fees, cap);

        log.info(() -> "Number of safe three-fee bundles = " + safe);
    }
}
